#!/usr/bin/env python3
"""Writes mixins/squaremap/core/src/assets.rs: the web frontend files the crate embeds."""
import os

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "mixins", "squaremap", "core")
files = []
for dirpath, _, names in os.walk(os.path.join(root, "web")):
    for n in names:
        files.append(os.path.relpath(os.path.join(dirpath, n), os.path.join(root, "web")).replace(os.sep, "/"))
files.sort()
out = ["//! The squaremap web frontend (MIT, see LICENSE; Leaflet: BSD-2-Clause), embedded.",
       "//! Generated by tools/gen_assets.py; do not edit.", "",
       "pub const FILES: &[(&str, &[u8])] = &["]
for f in files:
    out.append(f'    ("{f}", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/web/{f}"))),')
out += ["];", "", "pub fn file(path: &str) -> Option<&'static [u8]> {",
        "    FILES.iter().find(|(p, _)| *p == path).map(|(_, b)| *b)", "}", ""]
open(os.path.join(root, "src", "assets.rs"), "w").write("\n".join(out))
print(len(files), "files")
